(() => {
 const $=selector=>document.querySelector(selector),t=key=>window.TOCRI18n?.t(key)||key;
 const number=value=>new Intl.NumberFormat(document.documentElement.lang||'en',{maximumFractionDigits:0}).format(value);
 const copy=(key,values={})=>Object.entries(values).reduce((text,[key,value])=>text.replaceAll(`{${key}}`,number(value)),t(key));
 const el=(tag,text='',className='')=>{const node=document.createElement(tag);node.textContent=text;node.className=className;return node;};
 const button=(key,task)=>{const node=el('button',t(key),'text-button');node.type='button';node.onclick=()=>void workspaceTask(task);return node;};
 function setWorking(...nodes){const host=$('#scan-working-preview');host.replaceChildren(...nodes);host.closest('.scan-comparison')?.classList.toggle('has-working',nodes.length>0);}
 let scanPreviews=[],scanFiles=[],reports=[],controller=null,generation=0,workingCache=null,busy=false,progressState=null;
 const sameFiles=()=>scanFiles.length===files.length&&scanFiles.every((file,index)=>files[index]===file);
 function setBusy(value){busy=value;$('#scan-analyze').disabled=value;$('#scan-cancel').hidden=!value;$('#scan-preview').disabled=value||!scanPreviews[Number($('#scan-file').value)];$('#scan-reset').disabled=value;$('#pdf-order-open').disabled=value||!reports[Number($('#scan-file').value)]?.pdf;$('#scan-progress').setAttribute('aria-busy',String(value));}
 function progress(key,values){progressState={key,values};$('#scan-progress').textContent=copy(key,values);}
 function selectedReport(){const index=Number($('#scan-file').value),saved=fileCorrections.get(files[index])||{},originalPage=saved.pageOrder?.[scanPage-1]||scanPage;return {index,saved,report:reports[index],page:reports[index]?.pageReports.find(page=>page.number===originalPage),originalPage};}
 function updatePageOptions(){const {report,saved}=selectedReport();if(!report)return;$('#scan-pdf-page-label').hidden=!report.pdf||report.pages<2;$('#scan-pdf-page').replaceChildren(...Array.from({length:report.pages},(_,index)=>{const original=saved.pageOrder?.[index]||index+1,page=report.pageReports.find(page=>page.number===original),count=page?.warnings.length||0;return new Option(`${number(index+1)} / ${number(report.pages)}${original!==index+1?` · ${t('Originalseite')} ${number(original)}`:''}${count?` · ${number(count)} ${t('Hinweise')}`:''}`,String(index+1));}));$('#scan-pdf-page').value=String(scanPage);}
 function renderReports(){
  const host=$('#scan-reports'),open=host.querySelector('details')?.open,{page,report,index}=selectedReport();host.replaceChildren();if(!report){host.append(el('p',t('Diese Datei wurde noch nicht geprüft.'),'muted'));return;}
  const title=el('strong',`${scanFiles[index]?.name||report.name} · ${t('Originalseite')} ${number(selectedReport().originalPage)}`);title.dataset.noTranslate='';host.append(title);
  if(!page)host.append(el('p',t('Diese Seite wurde noch nicht geprüft. Vor dem Übersetzen visuell prüfen.'),'muted'));
  else if(page.status!=='analyzed')host.append(el('p',t('Diese Seite konnte nicht analysiert werden. Vor dem Übersetzen vollständig visuell prüfen.'),'error'));
  else{
   const facts=el('p',`${t('Helligkeit')}: ${number(page.brightness)} / ${number(255)} · ${t('Kontrast')}: ${number(page.contrast)} · ${t('Schärfeindikator')}: ${number(page.sharpness)}`,'muted');facts.dataset.noTranslate='';host.append(facts);
   if(page.resolution?.dpi!==null&&page.resolution?.dpi!==undefined)host.append(el('p',`${t('Geschätzte Bildauflösung')}: ${number(page.resolution.dpi)} dpi`,'muted'));
   else if(report.pdf)host.append(el('p',t('Bildauflösung nicht verlässlich aus dieser PDF-Seite ermittelt.'),'muted'));
   else host.append(el('p',`${number(page.width)} × ${number(page.height)} px`,'muted'));
   if(page.warnings.length){const list=el('ul');for(const warning of page.warnings)list.append(el('li',t(warning)));host.append(list);}else host.append(el('p',t('Keine heuristische Auffälligkeit. Ränder und Spiegelungen visuell prüfen.'),'muted'));
   if(page.orientationSuggestion){const rotation=el('p',`${t('Drehvorschlag für diese Seite')}: ${number(page.orientationSuggestion.rotation)}°`);rotation.dataset.noTranslate='';host.append(rotation,button('Drehvorschlag auswählen',async()=>{$('#scan-rotation').value=String(page.orientationSuggestion.rotation);$('#scan-preview').focus();}));}
   else host.append(el('p',t(page.orientationStatus==='text-baselines'?'Textzeilen überwiegend waagrecht; Ausrichtung visuell bestätigen.':'Ausrichtung unbekannt. Diese Seite bei Bedarf manuell drehen.'),'muted'));
   if(page.orientation&&page.orientation!==1)host.append(el('p',t('EXIF-Ausrichtung wird bei der Verarbeitung berücksichtigt.'),'muted'));
   if(page.warningCodes?.some(code=>['blur','dark','overexposed','low-resolution','low-resolution-pdf'].includes(code)))host.append(el('p',t('Bei schlechter Lesbarkeit über die Dateiauswahl eine bessere oder vollständigere Aufnahme ersetzen.'),'muted'),button('Zur Dateiauswahl',async()=>{window.TOCRDialogs.close($('#scan-dialog'));$('#file-list').scrollIntoView({block:'center'});$('#pick').focus();}));
   if(page.warningCodes?.includes('edge'))host.append(el('p',t('Randnahe Inhalte am Original prüfen. Zuschnitt nur wählen, wenn alle Angaben erhalten bleiben.'),'muted'),button('Zuschnitt am Original prüfen',async()=>scanCropCanvas?.focus()));
  }
  const flagged=report.pageReports.filter(page=>page.warnings?.length||page.status!=='analyzed');if(flagged.length){const details=el('details'),summary=el('summary',`${t('Seiten mit Hinweisen')}: ${number(flagged.length)}`);details.open=Boolean(open);details.append(summary);for(const item of flagged)details.append(button(`${t('Originalseite')} ${number(item.number)}`,async()=>{const order=fileCorrections.get(scanFiles[index])?.pageOrder;scanPage=order?order.indexOf(item.number)+1:item.number;$('#scan-rotation').value=String(fileCorrections.get(scanFiles[index])?.rotations?.[scanPage]??fileCorrections.get(scanFiles[index])?.rotation??0);renderReports();await drawScanCrop();}));host.append(details);}
  host.append(el('p',t('Heuristische Hinweise, keine verlässliche Erkennung aller Spiegelungen, Unschärfen oder abgeschnittenen Inhalte.'),'muted'));updatePageOptions();
 }
 async function renderWorking(index,correction,ticket){
  const file=scanFiles[index];if(!fileCorrections.has(file))return;const signature=JSON.stringify(correction);if(!workingCache||workingCache.file!==file||workingCache.signature!==signature){const result=await localRequest('/api/scan/correct',{file:{name:file.name,type:file.type,data:await fileBase64(file)},...correction}).then(response=>response.json());if(ticket!==drawGeneration||!sameFiles())return;workingCache={file,signature,result};}
  const {canvas}=await sourceCanvas(workingCache.result,scanPage);if(ticket!==drawGeneration||!sameFiles())return;canvas.setAttribute('role','img');canvas.setAttribute('aria-label',t('Korrigierte Arbeitskopie'));setWorking(el('strong',t('Arbeitskopie nach Korrektur')),canvas,el('p',t('Diese Arbeitskopie ist für den nächsten Auftrag vorgemerkt. Das Original bleibt unverändert.'),'muted'));
 }
let scanCropRect=null,scanCropCanvas=null,scanPage=1,scanPageCount=1,drawGeneration=0;
async function drawScanCrop(){
 const ticket=++drawGeneration,stage=$('#scan-crop-stage'),index=Number($('#scan-file').value),source=scanPreviews[index],imageSource=Boolean(source?.type?.startsWith('image/')),instructions=$('.scan-preview-label span');
 stage.replaceChildren();setWorking();if(!source){scanCropCanvas=null;return;}const saved=fileCorrections.get(files[index])||{};scanCropRect=imageSource?(saved.crop||null):(saved.crops?.[scanPage]||null);
 const originalPage=saved.pageOrder?.[scanPage-1]||scanPage,{canvas,pages}=await sourceCanvas(source,originalPage);if(ticket!==drawGeneration||files[index]!==scanFiles[index])return;scanPage=Math.min(scanPage,pages);scanCropCanvas=canvas;scanPageCount=pages;$('#scan-pdf-page-label').hidden=imageSource||pages<2;updatePageOptions();canvas.className='scan-crop-image';canvas.tabIndex=0;canvas.setAttribute('role','group');
 const cropInstructions='Rahmen ziehen oder Bild fokussieren: Eingabetaste setzt einen mittigen Zuschnitt · Pfeiltasten verschieben · Umschalt + Pfeiltasten ändern die Größe · Entf löscht.';
 canvas.setAttribute('aria-label',window.TOCRI18n.t('Zuschnitt. Eingabetaste setzt einen mittigen Rahmen. Pfeiltasten verschieben; Umschalt plus Pfeiltasten ändern die Größe. Entf löscht den Rahmen.'));
 if(instructions)instructions.textContent=window.TOCRI18n.t(cropInstructions);
 const frame=document.createElement('div');frame.className='scan-crop-frame';frame.append(canvas);const selection=document.createElement('div');selection.className='scan-crop-selection';selection.setAttribute('aria-hidden','true');frame.append(selection);stage.append(frame);
 function paint(){if(!scanCropRect){selection.hidden=true;return}selection.hidden=false;selection.style.left=`${scanCropRect[0]*100}%`;selection.style.top=`${scanCropRect[1]*100}%`;selection.style.width=`${scanCropRect[2]*100}%`;selection.style.height=`${scanCropRect[3]*100}%`}
 function announceCrop(){const status=$('#scan-crop-status');if(!scanCropRect)status.textContent=window.TOCRI18n.t('Kein Zuschnitt ausgewählt.');else status.textContent=window.TOCRI18n.t('Zuschnitt ausgewählt.')+' '+number(Math.round(scanCropRect[2]*100))+'% × '+number(Math.round(scanCropRect[3]*100))+'%'}
 {let start=null;const point=e=>{const r=canvas.getBoundingClientRect();return [Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))]};canvas.onkeydown=e=>{if(!['Enter','Delete','Backspace','ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const key=e.shiftKey&&e.key.startsWith('Arrow')?'Shift+'+e.key:e.key,step=e.shiftKey?.05:.01,next=window.adjustCropRect(scanCropRect,key,step);if(next===scanCropRect)return;scanCropRect=next;paint();announceCrop()};canvas.onpointerdown=e=>{if(e.button!==0)return;canvas.focus();canvas.setPointerCapture(e.pointerId);start=point(e);scanCropRect=[start[0],start[1],0,0];paint();announceCrop()};canvas.onpointermove=e=>{if(!start)return;const end=point(e),x=Math.min(start[0],end[0]),y=Math.min(start[1],end[1]);scanCropRect=[x,y,Math.abs(end[0]-start[0]),Math.abs(end[1]-start[1])];paint()};canvas.onpointerup=()=>{start=null;if(scanCropRect&&scanCropRect[2]<.025&&scanCropRect[3]<.025)scanCropRect=null;paint();announceCrop()};}
 paint();announceCrop();await renderWorking(index,saved,ticket);
}
 async function drawSelected(){const {saved,report}=selectedReport();$('#pdf-order-open').disabled=busy||!report?.pdf;$('#scan-rotation').value=String(saved.rotations?.[scanPage]??saved.rotation??0);renderReports();await drawScanCrop();}
 function cancel(){controller?.abort();controller=null;generation++;setBusy(false);progress('Prüfung abgebrochen. Nicht geprüfte Seiten bleiben offen.');}

 let orderDraft=null,orderFile=null;
 function clearOrder(){orderDraft=null;orderFile=null;$('#pdf-order-pages').replaceChildren();$('#pdf-order-note').textContent='';}
 function renderOrder(){const host=$('#pdf-order-pages');host.replaceChildren();if(!orderDraft)return;orderDraft.forEach((original,index)=>{const row=el('div','','scan-order-row');row.dataset.originalPage=String(original);row.append(el('span',`${number(index+1)} · ${t('Originalseite')} ${number(original)}`));for(const [delta,key]of [[-1,'Nach oben'],[1,'Nach unten']]){const move=button(key,async()=>{const next=index+delta;if(next<0||next>=orderDraft.length)return;[orderDraft[index],orderDraft[next]]=[orderDraft[next],orderDraft[index]];renderOrder();const moved=$('#pdf-order-pages').querySelector(`[data-original-page="${original}"]`),same=moved?.querySelector(`button[data-order-delta="${delta}"]`);(same&&!same.disabled?same:moved?.querySelector('button:not(:disabled)'))?.focus();});move.setAttribute('aria-label',`${t('Originalseite')} ${number(original)}: ${t(key)}`);move.dataset.orderDelta=String(delta);move.disabled=index+delta<0||index+delta>=orderDraft.length;row.append(move);}host.append(row);});host.append(button('Seitenreihenfolge übernehmen',async()=>{
   const {index,saved,originalPage}=selectedReport(),file=scanFiles[index];if(orderFile!==file||!sameFiles())throw new Error('Dateiauswahl wurde inzwischen geändert.');const oldOrder=saved.pageOrder||Array.from({length:orderDraft.length},(_,i)=>i+1),crops={},rotations={};orderDraft.forEach((original,newIndex)=>{const oldIndex=oldOrder.indexOf(original)+1;if(saved.crops?.[oldIndex])crops[newIndex+1]=saved.crops[oldIndex];if(saved.rotations?.[oldIndex]!==undefined)rotations[newIndex+1]=saved.rotations[oldIndex];});const correction={...saved,pageOrder:[...orderDraft],crops,...(saved.rotations?{rotations}:{})},newPage=orderDraft.indexOf(originalPage)+1,ticket=++drawGeneration,result=await localRequest('/api/scan/correct',{file:{name:file.name,type:file.type,data:await fileBase64(file)},...correction}).then(response=>response.json());const checked=await sourceCanvas(result,newPage);checked.canvas.width=1;checked.canvas.height=1;if(ticket!==drawGeneration||!sameFiles())throw new Error('Dateiauswahl wurde inzwischen geändert.');fileCorrections.set(file,correction);workingCache={file,signature:JSON.stringify(correction),result};scanPage=newPage;clearOrder();invalidateDraft();window.scheduleStudioDraftSave();await drawSelected();
  }),button('Abbrechen',async()=>clearOrder()));}
 $('#pdf-order-open').onclick=()=>void workspaceTask(async()=>{const {index,report,saved}=selectedReport();if(!report?.pdf||!scanPreviews[index])throw new Error('Bitte zuerst eine PDF-Datei prüfen.');if(orderDraft){clearOrder();return;}orderFile=scanFiles[index];orderDraft=saved.pageOrder?[...saved.pageOrder]:Array.from({length:report.pages},(_,i)=>i+1);$('#pdf-order-note').textContent=t('Jede Originalseite bleibt genau einmal enthalten. Zuschnitt und Drehung bleiben ihrer Originalseite zugeordnet.');renderOrder();});
 $('#scan-cancel').onclick=cancel;
 $('#scan-file').onchange=()=>void workspaceTask(async()=>{scanPage=1;workingCache=null;clearOrder();await drawSelected();});
 $('#scan-pdf-page').onchange=()=>void workspaceTask(async()=>{scanPage=Number($('#scan-pdf-page').value)||1;await drawSelected();});
 $('#scan-analyze').onclick=()=>void workspaceTask(async()=>{
  if(!files.length)throw new Error('Bitte zuerst Dateien auswählen.');controller?.abort();const active=new AbortController();controller=active;const ticket=++generation;scanFiles=[...files];scanPreviews=[];reports=[];workingCache=null;clearOrder();scanPage=1;drawGeneration++;const selectedIndex=Math.min(Number($('#scan-file').value)||0,files.length-1);$('#scan-file').replaceChildren(...scanFiles.map((file,index)=>{const option=new Option(file.name,String(index));option.dataset.noTranslate='';return option;}));$('#scan-file').value=String(selectedIndex);$('#scan-crop-stage').replaceChildren();setWorking();$('#scan-reports').replaceChildren();setBusy(true);progress('Lokale Scanprüfung wird vorbereitet …');let complete=false;
  try{
   const response=await localRequest('/api/scan?stream=1',{files:await documentsForRequest(scanFiles)},active.signal);if(ticket!==generation)return;const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='';
   const consume=async event=>{if(ticket!==generation||!sameFiles()){active.abort();return;}
    if(event.type==='file'){scanPreviews[event.index]=event.preview;reports[event.index]={name:event.name,pdf:event.pdf,pages:event.pages,pageReports:[]};if(Number($('#scan-file').value)===event.index)await drawSelected();}
    if(event.type==='page'){const report=reports[event.index];if(!report)throw new Error('Ungültiger Prüfbericht.');report.pageReports.push(event.page);progress('Datei {file} von {total}: Seite {page} von {pages} geprüft.',{file:event.index+1,total:scanFiles.length,page:event.page.number,pages:report.pages});renderReports();}
    if(event.type==='complete'){complete=true;progress(event.complete?'Lokale Prüfung abgeschlossen. Hinweise ersetzen keine Sichtprüfung.':'Prüfung beendet; einzelne Seiten konnten nicht analysiert werden. Visuell prüfen.');}
    if(event.type==='error')throw new Error(event.message);
   };
   try{while(true){const {value,done}=await reader.read();if(done){buffer+=decoder.decode();break;}buffer+=decoder.decode(value,{stream:true});if(buffer.length>52*1024*1024)throw new Error('Der Prüfbericht ist zu groß.');let newline;while((newline=buffer.indexOf('\n'))>=0){const line=buffer.slice(0,newline);buffer=buffer.slice(newline+1);if(line)await consume(JSON.parse(line));}if(ticket!==generation)break;}if(buffer.trim())await consume(JSON.parse(buffer));if(ticket===generation&&!complete)throw new Error('Die Scanprüfung wurde nicht vollständig abgeschlossen. Nicht geprüfte Seiten visuell prüfen.');}finally{reader.releaseLock();}
  }catch(error){if(active.signal.aborted){if(ticket===generation)progress('Prüfung abgebrochen. Nicht geprüfte Seiten bleiben offen.');}else{progress('Die Scanprüfung wurde nicht vollständig abgeschlossen. Nicht geprüfte Seiten visuell prüfen.');active.abort();throw error;}}
  finally{if(ticket===generation){controller=null;setBusy(false);renderReports();if($('#scan-dialog').dataset.focusCropOnReady==='true'){delete $('#scan-dialog').dataset.focusCropOnReady;if(matchMedia('(max-width: 599px)').matches)$('#scan-crop-stage').scrollIntoView({block:'center'});}}}
 });
 $('#scan-preview').onclick=()=>void workspaceTask(async()=>{
  const index=Number($('#scan-file').value),file=scanFiles[index],source=scanPreviews[index];if(!file||!sameFiles()||!source)throw new Error('Bitte Dateiauswahl zuerst prüfen.');const previous=fileCorrections.get(file)||{},pdf=source.type==='application/pdf',crops={...(previous.crops||{})};if(scanCropRect)crops[scanPage]=scanCropRect;else delete crops[scanPage];const correction=pdf?{...previous,rotations:{...(previous.rotations||{}),[scanPage]:Number($('#scan-rotation').value)},crops}:{...previous,rotation:Number($('#scan-rotation').value),crop:scanCropRect};const ticket=++drawGeneration,selectedPage=scanPage;
  const result=await localRequest('/api/scan/correct',{file:{name:file.name,type:file.type,data:await fileBase64(file)},...correction}).then(response=>response.json());const {canvas}=await sourceCanvas(result,selectedPage);if(!sameFiles()||ticket!==drawGeneration||scanPage!==selectedPage)throw new Error('Dateiauswahl wurde inzwischen geändert.');canvas.setAttribute('role','img');canvas.setAttribute('aria-label',t('Korrigierte Arbeitskopie'));setWorking(el('strong',t('Arbeitskopie nach Korrektur')),canvas,el('p',t('Diese Arbeitskopie ist für den nächsten Auftrag vorgemerkt. Das Original bleibt unverändert.'),'muted'));$('.scan-comparison').scrollIntoView({block:'start',behavior:'instant'});fileCorrections.set(file,correction);workingCache={file,signature:JSON.stringify(correction),result};invalidateDraft();window.scheduleStudioDraftSave();renderReports();
 });
 $('#scan-reset').onclick=()=>void workspaceTask(async()=>{const file=scanFiles[Number($('#scan-file').value)];if(file)fileCorrections.delete(file);clearOrder();workingCache=null;scanCropRect=null;scanPage=1;$('#scan-rotation').value='0';await drawSelected();invalidateDraft();window.scheduleStudioDraftSave();toast(t('Arbeitskopie zurückgesetzt.'));});
 $('#scan-dialog').addEventListener('close',()=>{controller?.abort();controller=null;generation++;drawGeneration++;scanPreviews=[];scanFiles=[];reports=[];workingCache=null;clearOrder();scanCropCanvas=null;$('#scan-crop-stage').replaceChildren();setWorking();$('#scan-reports').replaceChildren();setBusy(false);});
 window.addEventListener('translateocr-locale',()=>{if($('#scan-dialog').open){if(progressState)progress(progressState.key,progressState.values);renderReports();if(orderDraft){renderOrder();$('#pdf-order-note').textContent=t('Jede Originalseite bleibt genau einmal enthalten. Zuschnitt und Drehung bleiben ihrer Originalseite zugeordnet.');}$('#scan-crop-status').textContent=scanCropRect?t('Zuschnitt ausgewählt.')+' '+number(Math.round(scanCropRect[2]*100))+'% × '+number(Math.round(scanCropRect[3]*100))+'%':t('Kein Zuschnitt ausgewählt.');}});
 new MutationObserver(()=>{if(controller&&!sameFiles())cancel();}).observe($('#file-list'),{childList:true});
})();
